questionvariables.text:
length_dp: 1 + rand(2);
length_scale: 10^length_dp;
length_steps: rand(400*length_scale/10 + 1);
plot_length: float(60 + length_steps/length_scale);
plot_length_disp: float(plot_length);
plot_length_err: float(0.5/length_scale);

width_dp: 1 + rand(2);
width_scale: 10^width_dp;
width_steps: rand(250*width_scale/10 + 1);
plot_width: float(20 + width_steps/width_scale);
plot_width_disp: float(plot_width);
plot_width_err: float(0.5/width_scale);

max_plot_length: plot_length + plot_length_err;
min_plot_length: plot_length - plot_length_err;

max_plot_width: plot_width + plot_width_err;
min_plot_width: plot_width - plot_width_err;

W_plot_area: plot_length * plot_width;

max_plot_area: max_plot_length * max_plot_width;
min_plot_area: min_plot_length * min_plot_width;

ta1: max_plot_area - W_plot_area;
ta2: ta1 / W_plot_area;
ta3: ta2 * 100;
